package shop.ultimatesmp.tempgrants;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
class GrantTest {
 @TempDir Path temp;
 @Test void parsesExplicitWallClockTimers(){assertEquals(1000,Grant.duration("1s"));assertEquals(1800000,Grant.duration("30m"));assertEquals(7200000,Grant.duration("2h"));assertEquals(604800000,Grant.duration("7d"));assertEquals(2419200000L,Grant.duration("4w"));}
 @Test void rejectsAmbiguousAndUnboundedTimers(){for(String value:List.of("0s","-1h","forever","5","1h30m","9999999999w"))assertThrows(IllegalArgumentException.class,()->Grant.duration(value));}
 @Test void extendsActiveTimeButStartsExpiredGrantsNow(){assertEquals(16000,Grant.extend(11000,10000,5000));assertEquals(15000,Grant.extend(9000,10000,5000));assertThrows(IllegalArgumentException.class,()->Grant.extend(10000+Grant.MAX_DURATION,10000,1000));}
 @Test void exactPermissionNodesOnly(){Grant.permission("maxhomes.9");Grant.permission("edit.spawn");for(String value:List.of("*","essentials.*","bad node",""))assertThrows(IllegalArgumentException.class,()->Grant.permission(value));}
 @Test void grantKeysDoNotTurnPermissionDotsIntoYamlPaths(){String key=new Grant("perm","maxhomes.9",0).key();assertFalse(key.contains("."));assertNotEquals(key,new Grant("perm","maxhomes.3",0).key());}
 @Test void localOneUsePersistsAndDoesNotRefreshExpiryOnDuplicate()throws Exception{var a=new GrantStore(temp.resolve("data.yml"),null,"","");a.initialize();UUID id=UUID.randomUUID(),player=UUID.randomUUID();a.mint(List.of(new GrantStore.Voucher(id,"rank","ULTIMATE_PLUS",5000,"Custom Name")));assertTrue(a.redeem(id,player,10000).applied());var b=new GrantStore(temp.resolve("data.yml"),null,"","");assertFalse(b.redeem(id,UUID.randomUUID(),11000).applied());assertEquals(15000,b.active(player,14000).getFirst().expiry());assertTrue(b.active(player,15000).isEmpty());}
 @Test void multipleVouchersExtendOnlyMatchingGrant()throws Exception{var s=new GrantStore(temp.resolve("data.yml"),null,"","");s.initialize();UUID player=UUID.randomUUID(),one=UUID.randomUUID(),two=UUID.randomUUID(),three=UUID.randomUUID();s.mint(List.of(new GrantStore.Voucher(one,"perm","maxhomes.9",5000,"Homes"),new GrantStore.Voucher(two,"perm","maxhomes.9",5000,"Homes"),new GrantStore.Voucher(three,"rank","ULTIMATE_PLUS",5000,"Rank")));s.redeem(one,player,10000);s.redeem(two,player,11000);s.redeem(three,player,11000);var grants=s.active(player,12000);assertEquals(2,grants.size());assertEquals(20000,grants.stream().filter(g->g.kind().equals("perm")).findFirst().orElseThrow().expiry());}
 @Test void mysqlCopyRaceHasOnlyOneWinnerAndSurvivesStoreRecreation()throws Exception{String url=System.getenv("TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);String user=System.getenv("TEST_DB_USER"),pass=System.getenv("TEST_DB_PASSWORD");var a=new GrantStore(temp.resolve("unused"),url,user,pass);var b=new GrantStore(temp.resolve("unused2"),url,user,pass);a.initialize();UUID id=UUID.randomUUID(),p=UUID.randomUUID(),q=UUID.randomUUID();a.mint(List.of(new GrantStore.Voucher(id,"rank","ULTIMATE_PLUS",5000,"Name")));try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var x=pool.submit(()->a.redeem(id,p,10000));var y=pool.submit(()->b.redeem(id,q,10000));boolean won=x.get(10,TimeUnit.SECONDS).applied(),other=y.get(10,TimeUnit.SECONDS).applied();assertNotEquals(won,other);assertEquals(15000,b.active(won?p:q,14000).getFirst().expiry());assertTrue(b.active(won?q:p,14000).isEmpty());}assertFalse(a.redeem(id,p,11000).applied());}
 @Test void crateTemplateMintsFreshIndependentOneUseCopies()throws Exception{var s=new GrantStore(temp.resolve("data.yml"),null,"","");s.initialize();UUID source=UUID.randomUUID(),player=UUID.randomUUID();s.mint(List.of(new GrantStore.Voucher(source,"rank","ULTIMATE_PLUS",5000,"Custom crate name")));var one=s.copyVoucher(source);var two=s.copyVoucher(source);assertNotEquals(one.id(),two.id());assertNotEquals(source,one.id());assertEquals("Custom crate name",two.name());assertTrue(s.redeem(one.id(),player,10000).applied());assertTrue(s.redeem(two.id(),player,10000).applied());assertEquals(20000,s.active(player,10000).getFirst().expiry());assertFalse(s.redeem(one.id(),player,10000).applied());}
 @Test void unknownVoucherDoesNotCreateGrant()throws Exception{var s=new GrantStore(temp.resolve("data.yml"),null,"","");s.initialize();UUID player=UUID.randomUUID();assertFalse(s.redeem(UUID.randomUUID(),player,10000).applied());assertTrue(s.active(player,10000).isEmpty());}
}
